@rendermode InteractiveServer
@inject IChatService ChatService
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout">
    @* Left Sidebar — Channel List *@
    <aside class="channel-sidebar">
        <div class="sidebar-header">
            <h2>Channels</h2>
        </div>
        <ul class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var channel in _channels)
                {
                    <li class="channel-item @(channel.Id == _activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(channel)">
                        <div class="channel-name"># @channel.Name</div>
                        <div class="channel-description">@TruncateDescription(channel.Description)</div>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* Main Message Area *@
    <main class="message-area @(_threadOpen ? "with-thread" : "full-width")">
        @if (_activeChannel is not null)
        {
            <div class="message-header">
                <h3># @_activeChannel.Name</h3>
                <p>@_activeChannel.Description</p>
            </div>

            <div class="message-list" @ref="_messageListRef" @onscroll="OnMessageListScroll">
                @if (_loadingOlder)
                {
                    <div class="loading-indicator">Loading older messages...</div>
                }
                @if (_messages is not null)
                {
                    @foreach (var message in _messages)
                    {
                        <div class="message-item" @onmouseenter="() => _hoveredMessageId = message.Id"
                             @onmouseleave="() => _hoveredMessageId = null">
                            <div class="message-meta">
                                <span class="message-author">@message.Author</span>
                                <span class="message-time">@FormatRelativeTime(message.SentAt)</span>
                            </div>
                            <div class="message-content">@message.Content</div>

                            @if (message.Reactions.Count > 0)
                            {
                                <div class="reaction-list">
                                    @foreach (var reaction in message.Reactions)
                                    {
                                        <span class="reaction-badge" title="@string.Join(", ", reaction.Users)">
                                            @reaction.Emoji @reaction.Users.Count
                                        </span>
                                    }
                                </div>
                            }

                            @if (_threadSummaries.TryGetValue(message.Id, out var thread))
                            {
                                <button class="thread-link" @onclick="() => OpenThreadAsync(message.Id)">
                                    @thread.ReplyCount replies — last reply @FormatRelativeTime(thread.LastReplyAt)
                                </button>
                            }

                            @if (_hoveredMessageId == message.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" @onclick="() => OpenThreadAsync(message.Id)" title="Reply in thread">
                                        💬 Reply
                                    </button>
                                    <button class="action-btn" @onclick="() => ToggleEmojiPicker(message.Id)" title="Add reaction">
                                        😀 React
                                    </button>
                                </div>
                                @if (_emojiPickerMessageId == message.Id)
                                {
                                    <div class="emoji-picker">
                                        @foreach (var emoji in _commonEmojis)
                                        {
                                            <button class="emoji-option" @onclick="() => AddReactionAsync(message.Id, emoji)">
                                                @emoji
                                            </button>
                                        }
                                    </div>
                                }
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea @bind="_newMessageContent" @bind:event="oninput"
                          placeholder="Type a message..."
                          @onkeydown="OnMessageKeyDown"></textarea>
                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(_newMessageContent)">
                    Send
                </button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </main>

    @* Right Panel — Thread View *@
    @if (_threadOpen && _threadRootMessage is not null)
    {
        <aside class="thread-panel">
            <div class="thread-header">
                <h3>Thread</h3>
                <button class="close-thread-btn" @onclick="CloseThread">✕</button>
            </div>
            <div class="thread-root-message">
                <div class="message-meta">
                    <span class="message-author">@_threadRootMessage.Author</span>
                    <span class="message-time">@FormatRelativeTime(_threadRootMessage.SentAt)</span>
                </div>
                <div class="message-content">@_threadRootMessage.Content</div>
            </div>
            <div class="thread-replies">
                @if (_threadMessages is not null)
                {
                    @foreach (var reply in _threadMessages)
                    {
                        <div class="message-item">
                            <div class="message-meta">
                                <span class="message-author">@reply.Author</span>
                                <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                            </div>
                            <div class="message-content">@reply.Content</div>
                        </div>
                    }
                }
            </div>
            <div class="message-input-area">
                <textarea @bind="_threadReplyContent" @bind:event="oninput"
                          placeholder="Reply in thread..."
                          @onkeydown="OnThreadKeyDown"></textarea>
                <button class="send-btn" @onclick="SendThreadReplyAsync" disabled="@string.IsNullOrWhiteSpace(_threadReplyContent)">
                    Reply
                </button>
            </div>
        </aside>
    }
</div>

@code {
    private List<Channel>? _channels;
    private List<Message>? _messages;
    private List<Message>? _threadMessages;
    private Message? _threadRootMessage;
    private Dictionary<int, ThreadSummary> _threadSummaries = new();

    private Channel? _activeChannel;
    private int? _activeChannelId;
    private bool _threadOpen;
    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;
    private bool _loadingOlder;
    private bool _allOlderLoaded;

    private string _newMessageContent = string.Empty;
    private string _threadReplyContent = string.Empty;

    private ElementReference _messageListRef;
    private DotNetObjectReference<Chat>? _dotNetRef;
    private IJSObjectReference? _jsModule;

    private const int PageSize = 30;
    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _jsModule = await JS.InvokeAsync<IJSObjectReference>("import",
                "./Components/Pages/Chat.razor.js");
        }
    }

    private async Task SelectChannelAsync(Channel channel)
    {
        _activeChannel = channel;
        _activeChannelId = channel.Id;
        _messages = null;
        _allOlderLoaded = false;
        _threadSummaries.Clear();
        _emojiPickerMessageId = null;

        var messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messages = messages;

        BuildThreadSummaries();

        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channel list to update unread counts
        _channels = await ChatService.GetChannelsAsync();

        await ScrollToBottom();
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageContent) || _activeChannelId is null)
            return;

        var message = await ChatService.SendMessageAsync(_activeChannelId.Value, _newMessageContent.Trim(), null);
        _newMessageContent = string.Empty;
        _messages ??= new();
        _messages.Add(message);

        await ScrollToBottom();
    }

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _threadOpen = true;
        _threadReplyContent = string.Empty;
        _threadRootMessage = _messages?.FirstOrDefault(m => m.Id == rootMessageId);
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = null;
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyContent) || _threadRootMessage is null || _activeChannelId is null)
            return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, _threadReplyContent.Trim(), _threadRootMessage.Id);
        _threadReplyContent = string.Empty;
        _threadMessages ??= new();
        _threadMessages.Add(reply);

        // Update thread summary
        if (_threadSummaries.ContainsKey(_threadRootMessage.Id))
        {
            var existing = _threadSummaries[_threadRootMessage.Id];
            _threadSummaries[_threadRootMessage.Id] = existing with
            {
                ReplyCount = existing.ReplyCount + 1,
                LastReplyAt = reply.SentAt
            };
        }
        else
        {
            _threadSummaries[_threadRootMessage.Id] = new ThreadSummary(_threadRootMessage.Id, 1, reply.SentAt);
        }
    }

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        _emojiPickerMessageId = null;

        // Refresh messages to show updated reactions
        if (_activeChannelId is not null && _messages is not null)
        {
            var refreshed = await ChatService.GetMessagesAsync(_activeChannelId.Value, 0, _messages.Count);
            _messages = refreshed;
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task OnMessageListScroll()
    {
        if (_loadingOlder || _allOlderLoaded || _messages is null || _activeChannelId is null)
            return;

        if (_jsModule is not null)
        {
            var scrollTop = await _jsModule.InvokeAsync<double>("getScrollTop", _messageListRef);
            if (scrollTop < 50)
            {
                await LoadOlderMessagesAsync();
            }
        }
    }

    private async Task LoadOlderMessagesAsync()
    {
        if (_activeChannelId is null || _messages is null)
            return;

        _loadingOlder = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId.Value, _messages.Count, PageSize);
        if (older.Count == 0)
        {
            _allOlderLoaded = true;
        }
        else
        {
            _messages.InsertRange(0, older);
            BuildThreadSummaries();
        }

        _loadingOlder = false;
    }

    private void BuildThreadSummaries()
    {
        if (_messages is null) return;

        var replies = _messages.Where(m => m.ReplyToId is not null).ToList();
        var grouped = replies.GroupBy(m => m.ReplyToId!.Value);

        foreach (var group in grouped)
        {
            _threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt)
            );
        }
    }

    private async Task OnMessageKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessageAsync();
        }
    }

    private async Task OnThreadKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendThreadReplyAsync();
        }
    }

    private async Task ScrollToBottom()
    {
        await Task.Yield();
        if (_jsModule is not null)
        {
            await _jsModule.InvokeVoidAsync("scrollToBottom", _messageListRef);
        }
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }

    private static string TruncateDescription(string description)
    {
        return description.Length > 40 ? description[..37] + "..." : description;
    }

    public async ValueTask DisposeAsync()
    {
        _dotNetRef?.Dispose();
        if (_jsModule is not null)
        {
            await _jsModule.DisposeAsync();
        }
    }
}
"}

